DROP TABLE IF EXISTS `ppr_eight_d_report`;
CREATE TABLE `ppr_eight_d_report` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键，自增编号',
  `report_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '8D报告编号，全局唯一',
  `analysis_id` bigint unsigned NOT NULL COMMENT '关联分析任务ID，一次分析仅一份报告',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '报告标题',
  `d1` text COLLATE utf8mb4_unicode_ci COMMENT 'D1组建团队',
  `d2` text COLLATE utf8mb4_unicode_ci COMMENT 'D2问题描述',
  `d3` text COLLATE utf8mb4_unicode_ci COMMENT 'D3临时围堵措施',
  `d4` text COLLATE utf8mb4_unicode_ci COMMENT 'D4根因分析与验证',
  `d5` text COLLATE utf8mb4_unicode_ci COMMENT 'D5永久纠正措施选择',
  `d6` text COLLATE utf8mb4_unicode_ci COMMENT 'D6永久纠正措施实施与验证',
  `d7` text COLLATE utf8mb4_unicode_ci COMMENT 'D7预防再发生',
  `d8` text COLLATE utf8mb4_unicode_ci COMMENT 'D8团队表彰与结案',
  `status` enum('draft','finalized') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT '报告状态：草稿、已定稿',
  `owner_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '报告负责人',
  `finalized_at` datetime DEFAULT NULL COMMENT '报告定稿时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ppr_report_no` (`report_no`),
  UNIQUE KEY `uk_ppr_report_analysis` (`analysis_id`),
  CONSTRAINT `fk_ppr_report_analysis` FOREIGN KEY (`analysis_id`) REFERENCES `ppr_analysis_run` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PPR过程异常8D报告';
INSERT INTO `ppr_eight_d_report` (`id`,`report_no`,`analysis_id`,`title`,`d1`,`d2`,`d3`,`d4`,`d5`,`d6`,`d7`,`d8`,`status`,`owner_name`,`finalized_at`,`created_at`,`updated_at`) VALUES
(1,'8D-20261013014026-GS97',1,'QE-20261010-001 过程质量异常8D报告','质量工程师（主责）、生产领班、设备工程师、检验员。具体成员与职责待确认。','PPR S2.5 25×4.2 瓷芯管 / 批次 12121D0032 触发“待复核趋势”。连续3个可比较点下降，规则参数待现场验证','隔离异常时段相关产品并加密复检；核对原始检验记录与设备运行记录；隔离范围由质量工程师最终核定。','【触发规则与限值对照】待复核趋势：当前观测值 4.2600 mm，连续3个可比较点下降，规则参数待现场验证。\n验证发现：现场复核记录完整，确认作为报告输入\n\n【变化趋势观察】最近 3 个同批次可比较点由 4.320 变化至 4.260 mm，净变化 -0.060 mm。\n验证发现：现场复核记录完整，确认作为报告输入\n\n【同期设备因素】同批次同期关联到 3 条设备采集数据，可优先核查温度、压力与牵引速度是否在异常前后发生变化。\n验证发现：现场复核记录完整，确认作为报告输入','确认复测、参数核对和异常批次处置方案。','措施已实施并完成连续三批验证。','更新检验频次、预警规则和设备点检标准。','完成结案复盘并确认团队贡献。','finalized','E2E测试','2026-10-13 01:40:26.000','2026-10-13 01:40:26.000','2026-10-13 01:40:26.000'),
(4,'8D-20261014012159-CI2R',17,'QE-20261010-004WT 过程质量异常8D报告','质量工程师（主责）、生产领班、设备工程师、检验员。具体成员与职责待确认。','PPR S2.5 25×4.2 瓷芯管 / 批次 12121D0032 触发“连续3点接近区间边界”。4.200 mm–4.800 mm，连续 3 点进入接近带（距下限 ≤ 0.090 mm，为区间宽度的 15%）：4.290 / 4.260 / 4.270','隔离异常时段相关产品并加密复检；核对原始检验记录与设备运行记录；隔离范围由质量工程师最终核定。','尚无工程师确认的诊断结论，请返回诊断页完成验证。',NULL,NULL,NULL,NULL,'draft','质量工程师',NULL,'2026-10-14 01:21:59.000','2026-10-14 01:21:59.000'),
(5,'8D-20261014021650-OC4X',20,'QE-20261010-004WT 过程质量异常8D报告','质量工程师（主责）、生产领班、设备工程师、检验员。具体成员与职责待确认。','PPR S2.5 25×4.2 瓷芯管 / 批次 12121D0032 触发“连续3点接近区间边界”。4.200 mm–4.800 mm，连续 3 点进入接近带（距下限 ≤ 0.090 mm，为区间宽度的 15%）：4.290 / 4.260 / 4.270','隔离异常时段相关产品并加密复检；核对原始检验记录与设备运行记录；隔离范围由质量工程师最终核定。','【测量与数据有效性】本轮 min_wall_thickness 接近下限可能是测量口径或截面可比性问题（最薄点位置、测量温度、调节时间或测量截面变动）导致，而非制品壁厚真实整体下移。\n验证发现：123455',NULL,NULL,NULL,NULL,'draft','质量工程师',NULL,'2026-10-14 02:16:50.000','2026-10-14 02:16:50.000');

DROP TABLE IF EXISTS `ppr_equipment`;
CREATE TABLE `ppr_equipment` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键，自增编号',
  `code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备编码，全局唯一',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备名称',
