DROP TABLE IF EXISTS `ppr_history_archive`;
CREATE TABLE `ppr_history_archive` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键，自增编号',
  `archive_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '归档编号，全局唯一',
  `report_id` bigint unsigned NOT NULL COMMENT '来源8D报告ID',
  `event_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源预警事件编号快照',
  `batch_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源生产批次号快照',
  `metric_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源异常指标编码快照',
  `risk_level` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源风险级别快照',
  `problem_summary` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题摘要快照',
  `confirmed_root_cause` text COLLATE utf8mb4_unicode_ci COMMENT '已确认根因或主要验证结论快照',
  `corrective_action` text COLLATE utf8mb4_unicode_ci COMMENT '永久纠正措施快照',
  `archived_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '归档操作人',
  `archived_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '归档时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ppr_history_archive_no` (`archive_no`),
  UNIQUE KEY `uk_ppr_history_report` (`report_id`),
  CONSTRAINT `fk_ppr_history_report` FOREIGN KEY (`report_id`) REFERENCES `ppr_eight_d_report` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PPR质量异常历史归档';
INSERT INTO `ppr_history_archive` (`id`,`archive_no`,`report_id`,`event_no`,`batch_no`,`metric_code`,`risk_level`,`problem_summary`,`confirmed_root_cause`,`corrective_action`,`archived_by`,`archived_at`) VALUES
(1,'AR-20261013014026-X9YV',1,'QE-20261010-001','12121D0032','min_wall_thickness','medium','PPR S2.5 25×4.2 瓷芯管 / 批次 12121D0032 触发“待复核趋势”。连续3个可比较点下降，规则参数待现场验证','待复核趋势：当前观测值 4.2600 mm，连续3个可比较点下降，规则参数待现场验证。；验证：现场复核记录完整，确认作为报告输入\n最近 3 个同批次可比较点由 4.320 变化至 4.260 mm，净变化 -0.060 mm。；验证：现场复核记录完整，确认作为报告输入\n同批次同期关联到 3 条设备采集数据，可优先核查温度、压力与牵引速度是否在异常前后发生变化。；验证：现场复核记录完整，确认作为报告输入','确认复测、参数核对和异常批次处置方案。\n措施已实施并完成连续三批验证。\n更新检验频次、预警规则和设备点检标准。','E2E测试','2026-10-13 01:40:26.000');

DROP TABLE IF EXISTS `ppr_metric`;
CREATE TABLE `ppr_metric` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键，自增编号',
  `code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '指标编码，全局唯一',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '指标名称',
  `unit` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '计量单位',
  `lower_limit` decimal(12,4) DEFAULT NULL COMMENT '已弃用：判定限值统一取产品规格表 ppr_product_spec，本列仅留有历史数据',
  `upper_limit` decimal(12,4) DEFAULT NULL COMMENT '已弃用：判定限值统一取产品规格表 ppr_product_spec，本列仅留有历史数据',
  `influences` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '可能影响因素，仅作为排查方向',
  `description` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '指标口径与说明',
  `status` enum('enabled','disabled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'enabled' COMMENT '状态：enabled启用、disabled停用',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ppr_metric_code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PPR质量指标与影响因素字典';
INSERT INTO `ppr_metric` (`id`,`code`,`name`,`unit`,`lower_limit`,`upper_limit`,`influences`,`description`,`status`,`created_at`,`updated_at`) VALUES
(1,'outer_diameter','外径','mm','25.0000','25.5000','定径套、真空度、冷却水温、牵引速度','测量管材外径；正式判定以适用标准和产品规格为准','enabled','2026-10-13 01:36:53.000','2026-10-13 01:36:53.000'),
(2,'min_wall_thickness','壁厚','mm','4.2000','4.8000','挤出量、牵引速度、模具偏心、原料波动','仅最薄点不能代表整体壁厚分布','enabled','2026-10-13 01:36:53.000','2026-10-13 06:21:56.000'),
